CREATE OR REPLACE FUNCTION public.manage_membership(member_id uuid, desired_status text, desired_roles text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE member public.memberships; BEGIN SELECT * INTO member FROM public.memberships WHERE id=member_id; IF NOT FOUND THEN RAISE EXCEPTION 'Vínculo não encontrado.'; END IF; PERFORM 1 FROM public.organizations WHERE id=member.organization_id FOR UPDATE; SELECT * INTO member FROM public.memberships WHERE id=member_id FOR UPDATE; IF member.user_id=auth.uid() OR NOT (public.is_superadmin() OR public.org_admin(member.organization_id)) THEN RAISE EXCEPTION 'Acesso não autorizado; seu próprio vínculo não pode ser alterado.'; END IF; IF cardinality(desired_roles)=0 OR desired_roles IS NULL OR NOT desired_roles <@ ARRAY['admin','broker']::text[] THEN RAISE EXCEPTION 'Papéis inválidos.'; END IF; UPDATE public.memberships SET status=desired_status WHERE id=member_id; DELETE FROM public.membership_roles WHERE membership_id=member_id AND NOT role=ANY(desired_roles); INSERT INTO public.membership_roles(membership_id,role) SELECT member_id,unnest(desired_roles) ON CONFLICT DO NOTHING; PERFORM public.assert_capacity(member.organization_id); INSERT INTO public.audit_logs(organization_id,actor_id,action,target_id,details) VALUES(member.organization_id,auth.uid(),'membership.updated',member_id,jsonb_build_object('status',desired_status,'roles',desired_roles)); END $$;